import json
from collections import Counter
from rewards.pbebench import reward

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

def apply_programs(inputs, programs):
    """Apply a sequence of programs to inputs."""
    results = []
    for inp in inputs:
        result = inp
        for a, b in programs:
            result = result.replace(a, b)
        results.append(result)
    return results

def score_programs(programs, entry, max_programs=5, max_pred_len=3, max_transform_len=3):
    """Score a program sequence using the verifier."""
    raw = ["replace('{}', '{}')".format(a, b) for a, b in programs]
    return reward(raw, True, entry, max_programs, max_pred_len, max_transform_len)

# Test the approach on demo 0
d = demos[0]
inputs = d['input_examples']
outputs = d['output_examples']
entry = {"inputs": inputs, "outputs": outputs}

# Find single replacements that work
def find_single_replacements(inp, out):
    """Find all single replace(A, B) that transform inp to out."""
    if inp == out:
        return []
    results = []
    for a_len in range(1, 4):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            b = out[start:start + a_len]
            if len(b) <= 3:
                result = inp.replace(a, b)
                if result == out:
                    results.append((a, b))
    return results

