    candidates = []
    for a_len in range(1, 4):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            b = out[start:start + a_len]
            if 0 <= len(b) <= 3:
                result = inp.replace(a, b)
                if result == out:
                    candidates.append((a, b))
    return candidates

def greedy_sequence_search(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3):
    """
    Build a sequence of programs greedily, re-extracting candidates from 
    intermediate results after each step.
    """
    n = len(inputs)
    current_programs = []

    for step in range(max_programs):
        # Compute current results
        current_results = [apply_programs_to_string(inp, current_programs) for inp in inputs]

        # Find remaining incorrect pairs
        remaining_pairs = [(inp, out) for inp, out in zip(inputs, outputs) 
                          if apply_programs_to_string(inp, current_programs) != out]

        if not remaining_pairs:
            break

        # Extract candidates from intermediate (already-transformed) inputs vs outputs
        all_cands = []
        for inp, out in remaining_pairs:
            all_cands.extend(find_candidates_from_pair(inp, out))

        # Score each candidate
        best_score = -1
        best_cand = None

        for a, b in set(all_cands):
            if len(a) < 1 or len(a) > max_pred_len:
                continue
            if len(b) > max_transform_len:
                continue

