from rewards.pbebench import reward

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

def find_candidates_from_pair(inp, out, max_pred_len=3, max_transform_len=3):
    """Find all single replacements (A, B) that transform inp to out."""
    if inp == out:
        return []
    candidates = set()

    # For each substring A of inp, try all possible B lengths
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:] + 'x' * (b_len - (len(out) - start))
                    b = out[start:]
                result = inp.replace(a, b)
                if result == out:
                    candidates.add((a, b))

    return list(candidates)

def apply_programs_to_string(s, programs):
    result = s
    for a, b in programs:
        result = result.replace(a, b)
    return result

def greedy_sequence_search(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3):
    n = len(inputs)
    current_programs = []

    for step in range(max_programs):
        current_results = [apply_programs_to_string(inp, current_programs) for inp in inputs]

        remaining_pairs = [(inp, out) for inp, out in zip(inputs, outputs) 
                          if apply_programs_to_string(inp, current_programs) != out]

        if not remaining_pairs:
            break

        all_cands = []
        for inp, out in remaining_pairs:
            all_cands.extend(find_candidates_from_pair(inp, out, max_pred_len, max_transform_len))

        best_score = -1
        best_cand = None

        for a, b in set(all_cands):
            if len(a) < 1 or len(a) > max_pred_len:
                continue
            if len(b) > max_transform_len:
                continue

            test_programs = current_programs + [(a, b)]
            correct = sum(1 for inp, out in zip(inputs, outputs)
                         if apply_programs_to_string(inp, test_programs) == out)
            score = correct / n

            if score > best_score:
                best_score = score
                best_cand = (a, b)

        if best_cand and best_score > 0:
            current_programs.append(best_cand)

        if best_score >= 1.0:
            break

