import json
import re
import random
from collections import Counter
from rewards.pbebench import reward
from itertools import combinations, permutations

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

def apply_programs_to_string(s, programs):
    result = s
    for a, b in programs:
        result = result.replace(a, b)
    return result

def score_programs(programs, inputs, outputs):
    correct = sum(1 for i, o in zip(inputs, outputs)
                 if apply_programs_to_string(i, programs) == o)
    return correct / len(inputs)

def find_candidates_from_pair(inp, out, max_pred_len=3, max_transform_len=3):
    if inp == out:
        return []
    candidates = set()
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = inp.replace(a, b)
                if result == out:
                    candidates.add((a, b))
    return list(candidates)

def find_candidates_from_intermediate(inp, out, programs, max_pred_len=3, max_transform_len=3):
    intermediate = apply_programs_to_string(inp, programs)
    return find_candidates_from_pair(intermediate, out, max_pred_len, max_transform_len)

def build_program_sequence(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3, random_seed=None):
    """Build a program sequence using iterative greedy search."""
    n = len(inputs)
    current_programs = []

    for step in range(max_programs):
        failing = [(i, o) for i, o in zip(inputs, outputs) 
                  if apply_programs_to_string(i, current_programs) != o]

        if not failing:
            break

        all_cands = set()
        for inp, out in failing:
            all_cands.update(find_candidates_from_intermediate(inp, out, current_programs, max_pred_len, max_transform_len))
        for inp, out in zip(inputs, outputs):
            all_cands.update(find_candidates_from_pair(inp, out, max_pred_len, max_transform_len))

        # Score each candidate
        scored = []
        for a, b in all_cands:
            if len(a) < 1 or len(a) > max_pred_len or len(b) > max_transform_len:
                continue
            if (a, b) in current_programs:
                continue
            test = current_programs + [(a, b)]
            s = score_programs(test, inputs, outputs)
            scored.append((s, (a, b)))

        # Sort by score and pick top candidates for exploration
        scored.sort(reverse=True)
        top_candidates = scored[:20]  # Limit to top 20

        # Pick the best one
        if top_candidates:
            current_programs.append(top_candidates[0][1])

        if len(scored) > 0 and scored[0][0] >= 1.0:
            break

    return current_programs

def try_reordering(programs, inputs, outputs, max_programs):
    """Try reordering the program sequence."""
    if len(programs) <= max_programs:
        best_score = score_programs(programs, inputs, outputs)
        best_programs = list(programs)

        # Try all permutations for small sequences
        if len(programs) <= 7:
            for perm in permutations(programs):
                s = score_programs(perm, inputs, outputs)
                if s > best_score:
                    best_score = s
                    best_programs = list(perm)
                if s >= 1.0:
                    return best_programs

        # Try swapping adjacent pairs
        changed = True
        while changed and best_score < 1.0:
            changed = False
            for i in range(len(best_programs) - 1):
                swapped = list(best_programs)
                swapped[i], swapped[i+1] = swapped[i+1], swapped[i]
                s = score_programs(swapped, inputs, outputs)
                if s > best_score:
                    best_score = s
                    best_programs = swapped
                    changed = True

        return best_programs

    return list(programs)

def try_inserting(programs, inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3):
    """Try inserting new programs into existing sequence."""
    n = len(inputs)
    best_score = score_programs(programs, inputs, outputs)
    best_programs = list(programs)

    # Generate candidates from failing pairs
    failing = [(i, o) for i, o in zip(inputs, outputs) 
              if apply_programs_to_string(i, programs) != o]

    if failing:
        all_cands = set()
        for inp, out in failing:
            all_cands.update(find_candidates_from_intermediate(inp, out, programs, max_pred_len, max_transform_len))

        for a, b in all_cands:
            if len(a) < 1 or len(a) > max_pred_len or len(b) > max_transform_len:
                continue
            if (a, b) in programs:
                continue

            # Try inserting at each position
            for pos in range(len(programs) + 1):
                test = list(programs)
                test.insert(pos, (a, b))
                s = score_programs(tuple(test), inputs, outputs)
                if s > best_score:
                    best_score = s
                    best_programs = test

        return best_programs

    return best_programs

def multi_start_search(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3, num_starts=10):
    """Try multiple starting points and refine."""
    best_programs = []
    best_score = 0

    for start in range(num_starts):
        random.seed(start)

        # Build initial sequence
        programs = build_program_sequence(inputs, outputs, max_programs, max_pred_len, max_transform_len)

        # Try reordering
        programs = try_reordering(programs, inputs, outputs, max_programs)

        # Try inserting
        programs = try_inserting(programs, inputs, outputs, max_programs, max_pred_len, max_transform_len)

        # Try reordering again
        programs = try_reordering(programs, inputs, outputs, max_programs)

        score = score_programs(programs, inputs, outputs)
        if score > best_score:
            best_score = score
            best_programs = programs

        if best_score >= 1.0:
            return best_programs

    return best_programs

# Test on demos 1, 5, 9 (the failures)
for idx in [1, 5, 9]:
    d = demos[idx]
    entry = {"inputs": d['input_examples'], "outputs": d['output_examples']}
    mp = 20
    programs = multi_start_search(d['input_examples'], d['output_examples'], max_programs=mp, num_starts=5)
    raw = ["replace('{}', '{}')".format(a, b) for a, b in programs]
    res = reward(raw, True, entry, max_programs=mp, max_pred_len=3, max_transform_len=3)
    status = "✓" if res['value'] >= 1.0 else f"✗ ({res['value']})"
    print(f"Demo {idx}: {status}, programs={len(programs)}")
    if res['value'] < 1.0:
        print(f"  Programs: {raw[:5]}")
        print(f"  Message: {res.get('message', '')[:200]}")

