def find_candidates_from_pair(inp, out, max_pred_len=3, max_transform_len=3):
    if inp == out:
        return []
    candidates = set()
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = inp.replace(a, b)
                if result == out:
                    candidates.add((a, b))
    return list(candidates)

def find_candidates_from_intermediate(inp, out, programs, max_pred_len=3, max_transform_len=3):
    intermediate = apply_programs_to_string(inp, programs)
    return find_candidates_from_pair(intermediate, out, max_pred_len, max_transform_len)

def greedy_search(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3, num_candidates=30):
    """Greedy search with top-k candidates at each step."""
    n = len(inputs)
    current_programs = []

    for step in range(max_programs):
        failing = [(i, o) for i, o in zip(inputs, outputs) 
                  if apply_programs_to_string(i, current_programs) != o]

        if not failing:
            break

        all_cands = set()
        for inp, out in failing:
            all_cands.update(find_candidates_from_intermediate(inp, out, current_programs, max_pred_len, max_transform_len))
        for inp, out in zip(inputs, outputs):
            all_cands.update(find_candidates_from_pair(inp, out, max_pred_len, max_transform_len))

        # Score each candidate
        scored = []
        for a, b in all_cands:
            if len(a) < 1 or len(a) > max_pred_len or len(b) > max_transform_len:
                continue
            if (a, b) in current_programs:
                continue
            test = current_programs + [(a, b)]
            s = score_programs(test, inputs, outputs)
            scored.append((s, (a, b)))

        scored.sort(reverse=True)

        # Try top candidates
        best_cand = None
        best_s = -1
        for s, cand in scored[:min(num_candidates, len(scored))]:
            if s > best_s:
                best_s = s
                best_cand = cand

        if best_cand and best_s > 0:
            current_programs.append(best_cand)

        if best_s >= 1.0:
            break

    return current_programs

def try_permutations(programs, inputs, outputs, max_programs):
    """Try all permutations of a program sequence."""
    if len(programs) > 8:
        return list(programs)  # Too many to permute

    best_score = score_programs(programs, inputs, outputs)
    best = list(programs)

    for perm in permutations(programs):
        s = score_programs(perm, inputs, outputs)
        if s > best_score:
            best_score = s
            best = list(perm)
        if s >= 1.0:
            return best

    return best

