import json
import random
from collections import Counter

with open('/workspace/DEMOS.json') as f:
    demos = json.load(f)

from rewards.pbebench import reward

def apply_programs_to_string(s, programs):
    result = s
    for a, b in programs:
        result = result.replace(a, b)
    return result

def score_programs(programs, inputs, outputs):
    if not programs:
        return 0.0
    correct = sum(1 for i, o in zip(inputs, outputs)
                 if apply_programs_to_string(i, programs) == o)
    return correct / len(inputs)

def find_candidates_from_pair(inp, out, max_pred_len=3, max_transform_len=3):
    """Find replace(A, B) that transforms inp to out."""
    if inp == out:
        return []
    candidates = set()
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = inp.replace(a, b)
                if result == out:
                    candidates.add((a, b))
    return list(candidates)

def find_candidates_from_intermediate(inp, out, programs, max_pred_len=3, max_transform_len=3):
    """Find replace(A, B) that transforms intermediate to out."""
    intermediate = apply_programs_to_string(inp, programs)
    return find_candidates_from_pair(intermediate, out, max_pred_len, max_transform_len)

def find_candidates_from_original(inp, out, programs, max_pred_len=3, max_transform_len=3):
    """Find replace(A, B) that partially transforms inp towards out."""
    intermediate = apply_programs_to_string(inp, programs)
    if intermediate == inp:
        return []  # No change, nothing new to find
    if intermediate == out:
        return []  # Already correct

    # Try all substrings of intermediate and corresponding substrings of out
    candidates = set()
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(intermediate) - a_len + 1):
            a = intermediate[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = intermediate.replace(a, b)
                # Check if this makes progress (closer to output)
                if result != intermediate:
                    # Count matching characters
                    matches = sum(1 for r, o in zip(result, out) if r == o)
                    current_matches = sum(1 for r, o in zip(intermediate, out) if r == o)
                    if matches > current_matches:
                        candidates.add((a, b))

    return list(candidates)

def greedy_sequence_build(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3, 
                           top_k=30):
    current_programs = []
    for step in range(max_programs):
        failing = [(i, o) for i, o in zip(inputs, outputs)
                  if apply_programs_to_string(i, current_programs) != o]
        if not failing:
            break

        # Generate candidates from intermediate states (direct matches)
        all_cands = set()
        for inp, out in failing:
            all_cands.update(find_candidates_from_intermediate(inp, out, current_programs,
                                                               max_pred_len, max_transform_len))

