                           top_k=30):
    current_programs = []
    for step in range(max_programs):
        failing = [(i, o) for i, o in zip(inputs, outputs)
                  if apply_programs_to_string(i, current_programs) != o]
        if not failing:
            break

        all_cands = set()
        for inp, out in failing:
            intermediate = apply_programs_to_string(inp, current_programs)
            cands = find_candidates_from_pair(intermediate, out, max_pred_len, max_transform_len)
            all_cands.update(cands)
            cands = find_candidates_for_progress(intermediate, out, max_pred_len, max_transform_len)
            all_cands.update(cands)

        scored = []
        for a, b in all_cands:
            if len(a) < 1 or len(a) > max_pred_len or len(b) > max_transform_len:
                continue
            if (a, b) in current_programs:
                continue
            test = current_programs + [(a, b)]
            s = score_programs(test, inputs, outputs)
