    return sum(1 for c1, c2 in zip(pad1, pad2) if c1 != c2)

def find_candidates_from_pair(inp, out, max_pred_len=3, max_transform_len=3):
    if inp == out:
        return []
    candidates = set()
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = inp.replace(a, b)
                if result == out:
                    candidates.add((a, b))
    return list(candidates)

def find_candidates_for_progress(inp, out, max_pred_len=3, max_transform_len=3):
    if inp == out:
        return []
    candidates = set()
    current_diff = edit_distance(inp, out)
    for a_len in range(1, max_pred_len + 1):
        for start in range(len(inp) - a_len + 1):
            a = inp[start:start + a_len]
            for b_len in range(max_transform_len + 1):
                if start + b_len <= len(out):
                    b = out[start:start + b_len]
                else:
                    b = out[start:]
                result = inp.replace(a, b)
                new_diff = edit_distance(result, out)
                if new_diff < current_diff:
                    candidates.add((a, b))
    return list(candidates)

def greedy_sequence_build(inputs, outputs, max_programs, max_pred_len=3, max_transform_len=3, 
                           top_k=30):
    current_programs = []
    for step in range(max_programs):
        failing = [(i, o) for i, o in zip(inputs, outputs)
                  if apply_programs_to_string(i, current_programs) != o]
        if not failing:
            break

        all_cands = set()
        for inp, out in failing:
            intermediate = apply_programs_to_string(inp, current_programs)
            cands = find_candidates_from_pair(intermediate, out, max_pred_len, max_transform_len)
            all_cands.update(cands)
            cands = find_candidates_for_progress(intermediate, out, max_pred_len, max_transform_len)
            all_cands.update(cands)

        scored = []
        for a, b in all_cands:
            if len(a) < 1 or len(a) > max_pred_len or len(b) > max_transform_len:
                continue
            if (a, b) in current_programs:
                continue
            test = current_programs + [(a, b)]
            s = score_programs(test, inputs, outputs)
            scored.append((s, (a, b)))

        scored.sort(reverse=True)
        best_cand = None
        best_s = -1
        for s, cand in scored[:min(top_k, len(scored))]:
            if s > best_s:
                best_s = s
                best_cand = cand

        if best_cand and best_s > 0:
            current_programs.append(best_cand)
        if best_s >= 1.0:
            break

    return current_programs

def find_best_ordering(programs, inputs, outputs, max_programs, max_shuffles=200):
    n = len(programs)
    best_score = score_programs(programs, inputs, outputs)
    best = list(programs)
    if n <= 8:
        for perm in permutations(programs):
            s = score_programs(perm, inputs, outputs)
            if s > best_score:
                best_score = s
                best = list(perm)
            if s >= 1.0:
                return best
        return best
    for _ in range(max_shuffles):
        shuffled = list(programs)
        random.shuffle(shuffled)
        s = score_programs(shuffled, inputs, outputs)
        if s > best_score:
            best_score = s
            best = list(shuffled)
        if s >= 1.0:
            return best
    changed = True
    while changed and best_score < 1.0:
        changed = False
        for i in range(len(best) - 1):
            swapped = list(best)
            swapped[i], swapped[i+1] = swapped[i+1], swapped[i]
            s = score_programs(swapped, inputs, outputs)
            if s > best_score:
                best_score = s
                best = swapped
                changed = True
    return best

def solve_pbe(examples, K=10, max_programs=20, max_pred_len=3, max_transform_len=3,
              num_starts=5, top_k=30, max_shuffles=200):
    """Main solver function for PBE tasks.

    examples: list of (input_string, output_string) pairs
    K: number of top programs to return
    max_programs: maximum number of programs allowed
    max_pred_len: maximum length of predicate A
    max_transform_len: maximum length of transform B
    num_starts: number of independent search restarts
    top_k: number of top candidates per step
    max_shuffles: max random shuffles for reordering
    """
    inputs = [e[0] for e in examples]
    outputs = [e[1] for e in examples]
    all_solutions = []
    best_score = 0

    for start in range(num_starts):
        random.seed(start)
        programs = greedy_sequence_build(inputs, outputs, max_programs, max_pred_len, max_transform_len, top_k)
        programs = find_best_ordering(programs, inputs, outputs, max_programs, max_shuffles)
        score = score_programs(programs, inputs, outputs)
        prog_tuple = tuple(programs)
        if not any(tuple(s[0]) == prog_tuple for s in all_solutions):
            all_solutions.append((prog_tuple, score))
        if score > best_score:
            best_score = score
        if best_score >= 1.0:
            break

    all_solutions.sort(key=lambda x: -x[1])
    top_solutions = all_solutions[:K]
    success = any(s >= 1.0 for _, s in top_solutions)

    results = []
    for programs, score in top_solutions:
        raw = ["replace('{}', '{}')".format(a, b) for a, b in programs]
        results.append({"program": raw, "score": score, "num_programs": len(programs)})

    return {"success": success, "program": results[0]["program"] if results else [], 
            "programs": [r["program"] for r in results], "scores": [r["score"] for r in results]}

# Test with both PBEBench-Lite (5 programs) and hard (20 programs) constraints
print("=== Final comprehensive test ===")
for mp in [5, 20]:
    label = "PBEBench-Lite (5)" if mp == 5 else "Hard (20)"
    pass_count = 0
    fail_count = 0
    for d in demos:
        result = solve_pbe(list(zip(d['input_examples'], d['output_examples'])),
                           K=3, max_programs=mp, num_starts=3, top_k=30, max_shuffles=100)
        entry = {"inputs": d['input_examples'], "outputs": d['output_examples']}
        raw = result["program"]
        res = reward(raw, True, entry, max_programs=mp, max_pred_len=3, max_transform_len=3)
        if res['value'] >= 1.0:
            pass_count += 1
        else:
            fail_count += 1
    print(f"{label}: {pass_count} pass, {fail_count} fail")
